package com.huawei.finance.domain.payroll;
import com.huawei.finance.contracts.port.TechDomainAgent; import java.time.Duration; import java.util.Map; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.AutoConfiguration; import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean; import org.springframework.context.annotation.Bean; import org.springframework.http.client.SimpleClientHttpRequestFactory; import org.springframework.web.client.RestClient;
@AutoConfiguration
public class PayrollDomainConfiguration {
    @Bean @ConditionalOnMissingBean(PayrollStatusPort.class) PayrollStatusPort payrollStatusPort(RestClient.Builder builder,@Value("${huawei.finance.backends.payroll.base-url:http://banking-systems-simulator:8090}")String baseUrl,@Value("${huawei.finance.backends.payroll.timeout:2s}")Duration timeout){var f=new SimpleClientHttpRequestFactory();f.setConnectTimeout(timeout);f.setReadTimeout(timeout);var c=builder.baseUrl(baseUrl).requestFactory(f).build();return principal->{Map<?,?>m=c.get().uri("/api/payroll/{principal}/status",principal).retrieve().body(Map.class);if(m==null)throw new IllegalStateException("empty payroll response");return new PayrollStatusPort.StatusView(v(m,"status"),v(m,"lastArrivalDate"),v(m,"employer"));};}
    @Bean @ConditionalOnMissingBean(name="payrollDomainAgent") TechDomainAgent payrollDomainAgent(PayrollStatusPort port){return new PayrollDomainAgent(port);} private static String v(Map<?,?>m,String k){Object value=m.get(k);return value==null?"":String.valueOf(value);}
}
